from collections.abc import Iterator
from contextlib import contextmanager
from typing import Any

from fastapi.testclient import TestClient

from telco_support_agent.app import create_app
from telco_support_agent.models import Source


class FakeGraph:
    def __init__(self) -> None:
        self.invocations: list[dict[str, Any]] = []

    def invoke(self, state: dict[str, Any]) -> dict[str, Any]:
        self.invocations.append(state)
        return {
            "question": state["question"],
            "answer": "Telco GO is de streaming-app van Telco.",
            "sources": [
                Source(
                    section_title="Telco GO",
                    url="https://www.telco.example/televisie/telco-go",
                )
            ],
            "outcome": "grounded",
        }


@contextmanager
def make_client() -> Iterator[tuple[TestClient, FakeGraph]]:
    fake = FakeGraph()
    app = create_app(graph_provider=lambda: fake)
    with TestClient(app) as client:  # runs lifespan so the graph is wired
        yield client, fake


def test_ask_returns_answer_sources_and_status() -> None:
    with make_client() as (client, fake):
        response = client.post("/ask", json={"question": "Wat is Telco GO?"})

    assert response.status_code == 200
    assert response.json() == {
        "answer": "Telco GO is de streaming-app van Telco.",
        "sources": [
            {
                "section_title": "Telco GO",
                "url": "https://www.telco.example/televisie/telco-go",
            }
        ],
        "status": "grounded",
    }
    assert fake.invocations == [{"question": "Wat is Telco GO?"}]


def test_ask_rejects_empty_question() -> None:
    with make_client() as (client, _):
        response = client.post("/ask", json={"question": ""})

    assert response.status_code == 422

